export function PresentationalComponent({
  name = "{{name}}",
  price = "{{price}}",
  variant = "{{variant}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12, width: 280, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 14px", fontFamily: "ui-monospace, monospace", fontSize: 11, color: "#24143099" }}>{name}(price, status) &mdash; no internal state</p>
      <div style={{ display: "flex", alignItems: "center", gap: 8, padding: 14, borderRadius: 8, background: "#ffffff", border: "1.5px solid #24143018" }}>
        <span style={{ fontWeight: 800, fontSize: 18, textDecoration: variant === "sold-out" ? "line-through" : "none", opacity: variant === "sold-out" ? .5 : 1 }}>{price}</span>
        {variant === "sale" && <span style={{ fontSize: 11, fontWeight: 700, padding: "3px 8px", borderRadius: 4, background: accent }}>Sale</span>}
        {variant === "sold-out" && <span style={{ fontSize: 11, fontWeight: 700, padding: "3px 8px", borderRadius: 4, background: "#24143018" }}>Sold out</span>}
      </div>
    </div>
  );
}
